var mode='j2c',tabs=document.getElementById('tabs');
var SAMPLE_J='[\n  {"name":"Ali","city":"Lahore","orders":12},\n  {"name":"Sara","city":"Karachi","orders":7},\n  {"name":"Bilal","city":"Islamabad","orders":23}\n]';
var SAMPLE_C='name,city,orders\nAli,Lahore,12\nSara,Karachi,7\nBilal,Islamabad,23';
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button');if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active');mode=b.getAttribute('data-m');
  document.getElementById('inLabel').textContent=mode==='j2c'?'JSON input':'CSV input';
  document.getElementById('outLabel').textContent=mode==='j2c'?'CSV output':'JSON output';
  document.getElementById('in').value='';document.getElementById('out').value='';
  document.getElementById('note').textContent='Paste your data and press Convert.';
  WT.resize();
});
function flat(obj,prefix,out){
  out=out||{};prefix=prefix||'';
  for(var k in obj){
    if(!Object.prototype.hasOwnProperty.call(obj,k))continue;
    var v=obj[k],key=prefix?prefix+'.'+k:k;
    if(v&&typeof v==='object'&&!Array.isArray(v)){flat(v,key,out);}
    else if(Array.isArray(v)){out[key]=v.join('; ');}
    else {out[key]=v===null||v===undefined?'':v;}
  }
  return out;
}
function cell(v){
  var s=String(v);
  return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;
}
function jsonToCsv(text){
  var data=JSON.parse(text);
  if(!Array.isArray(data)){data=[data];}
  if(!data.length){throw new Error('That JSON array is empty.');}
  var rows=data.map(function(r){return flat(r);});
  var cols=[];
  rows.forEach(function(r){for(var k in r){if(cols.indexOf(k)<0){cols.push(k);}}});
  var lines=[cols.map(cell).join(',')];
  rows.forEach(function(r){lines.push(cols.map(function(c){return cell(r[c]===undefined?'':r[c]);}).join(','));});
  return {text:lines.join('\n'),rows:rows.length,cols:cols.length};
}
function splitCsvLine(line){
  var out=[],cur='',q=false;
  for(var i=0;i<line.length;i++){
    var ch=line[i];
    if(q){
      if(ch==='"'&&line[i+1]==='"'){cur+='"';i++;}
      else if(ch==='"'){q=false;}
      else {cur+=ch;}
    } else {
      if(ch==='"'){q=true;}
      else if(ch===','){out.push(cur);cur='';}
      else {cur+=ch;}
    }
  }
  out.push(cur);return out;
}
function csvToJson(text){
  var lines=text.replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n').filter(function(l){return l.trim()!=='';});
  if(lines.length<2){throw new Error('Need a header row and at least one data row.');}
  var head=splitCsvLine(lines[0]);
  var rows=lines.slice(1).map(function(l){
    var parts=splitCsvLine(l),o={};
    head.forEach(function(h,i){
      var v=parts[i]===undefined?'':parts[i];
      o[h]=(v!==''&&!isNaN(v)&&/^-?\d*\.?\d+$/.test(v.trim()))?Number(v):v;
    });
    return o;
  });
  return {text:JSON.stringify(rows,null,2),rows:rows.length,cols:head.length};
}
function run(){
  var input=document.getElementById('in').value.trim(),note=document.getElementById('note');
  if(!input){document.getElementById('out').value='';note.textContent='Paste your data first, or press Load sample.';return;}
  try{
    var r=mode==='j2c'?jsonToCsv(input):csvToJson(input);
    document.getElementById('out').value=r.text;
    note.textContent='Converted '+r.rows+' rows and '+r.cols+' columns.';
  }catch(e){
    document.getElementById('out').value='';
    note.textContent='Could not convert that: '+e.message;
  }
  WT.resize();
}
document.getElementById('go').addEventListener('click',run);
document.getElementById('in').addEventListener('input',run);
document.getElementById('sample').addEventListener('click',function(){
  document.getElementById('in').value=mode==='j2c'?SAMPLE_J:SAMPLE_C;run();
});
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(document.getElementById('out').value);
  document.getElementById('note').textContent=ok?'Result copied to clipboard.':'Copy failed, select the text instead.';
});
document.getElementById('dl').addEventListener('click',function(){
  var v=document.getElementById('out').value;if(!v)return;
  var name=mode==='j2c'?'data.csv':'data.json';
  var type=mode==='j2c'?'text/csv':'application/json';
  try{
    var url=URL.createObjectURL(new Blob([v],{type:type}));
    var a=document.createElement('a');a.href=url;a.download=name;
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},2000);
    document.getElementById('note').textContent='Saved as '+name+'. Check your downloads folder.';
  }catch(e){
    document.getElementById('note').textContent='Download was blocked. Use Copy result instead.';
  }
});
